func TestRc4Rfc6229FirstBytes(emonT *testing.T) {
	// RFC 6229, 40-bit key 0102030405: keystream offset 0 is b2396305f03dc027...
	var o *port.Cells = port.NewCells()
	var p *port.Cells = port.NewCells()
	port.CryptoRc4(port.HexBlob("0102030405"), 0, 5, port.HexBlob("00000000 00000000 00000000 00000000"), 0, 16, o)
	port.AssertCellsHex(emonT, o, "b2396305f03dc027ccc3524a0a1118a8", "40-bit key, 16 bytes of keystream")
	// 128-bit key 0102..10: keystream starts 9ac7cc9a609d1ef7b2932899cde41b97
	port.CryptoRc4(port.HexBlob("0102030405060708090a0b0c0d0e0f10"), 0, 16, port.HexBlob("00000000 00000000 00000000 00000000"), 0, 16, p)
	port.AssertCellsHex(emonT, p, "9ac7cc9a609d1ef7b2932899cde41b97", "128-bit key")
}

