func TestAesFips197OneBlock(emonT *testing.T) {
	// FIPS 197 C.1 and C.3: AES-128 and AES-256, a zero IV makes CBC one ECB block.
	var o *port.Cells = port.NewCells()
	var p *port.Cells = port.NewCells()
	var q *port.Cells = port.NewCells()
	var r *port.Cells = port.NewCells()
	port.AssertEq(emonT, port.CryptoAesEncrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("00000000000000000000000000000000 00112233445566778899aabbccddeeff"), 0, 32, o), 16, "one block out")
	port.AssertCellsHex(emonT, o, "69c4e0d86a7b0430d8cdb78070b4c55a", "AES-128 encrypt")
	port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("00000000000000000000000000000000 69c4e0d86a7b0430d8cdb78070b4c55a"), 0, 32, 0, p)
	port.AssertCellsHex(emonT, p, "00112233445566778899aabbccddeeff", "AES-128 decrypt")
	port.CryptoAesEncrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, port.HexBlob("00000000000000000000000000000000 00112233445566778899aabbccddeeff"), 0, 32, q)
	port.AssertCellsHex(emonT, q, "8ea2b7ca516745bfeafc49904b496089", "AES-256 encrypt")
	port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, port.HexBlob("00000000000000000000000000000000 8ea2b7ca516745bfeafc49904b496089"), 0, 32, 0, r)
	port.AssertCellsHex(emonT, r, "00112233445566778899aabbccddeeff", "AES-256 decrypt")
}

