func TestAesPaddingIsStrippedOnlyWhenAsked(emonT *testing.T) {
	// Ciphertext made by the JDK's AES/CBC/PKCS5Padding; key 00..0f, IV 0f..00.
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var c *port.Cells = port.NewCells()
	var d *port.Cells = port.NewCells()
	var e *port.Cells = port.NewCells()
	port.AssertEq(emonT, port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489"), 0, 32, 1, a), 5, "five bytes once the padding is gone")
	port.AssertCellsHex(emonT, a, "68656c6c6f", "hello")
	port.AssertEq(emonT, port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489"), 0, 32, 0, b), 16, "sixteen with pad 0")
	port.AssertCellsHex(emonT, b, "68656c6c6f0b0b0b0b0b0b0b0b0b0b0b", "the padding is kept when not asked")
	port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100 ff14dbe405cc0ee24d0de41289f0fc981c8a2100b00814723d26cb8858d62767"), 0, 48, 1, c)
	port.AssertCellsHex(emonT, c, "303132333435363738396162636465666768696a", "twenty bytes across two blocks")
	port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100 ff14dbe405cc0ee24d0de41289f0fc988680054fc9016bbf4f4067cd27826cdb"), 0, 48, 1, d)
	port.AssertCellsHex(emonT, d, "30313233343536373839616263646566", "sixteen bytes: a whole block of padding is removed")
	port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), 0, 32, port.HexBlob("0f0e0d0c0b0a09080706050403020100 2e5a65859a9f16ccfc0dddb5306145a9"), 0, 32, 1, e)
	port.AssertCellsHex(emonT, e, "68656c6c6f", "AES-256 padded")
}

func TestAesShortAndRaggedInput(emonT *testing.T) {
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var c *port.Cells = port.NewCells()
	port.AssertEq(emonT, port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100"), 0, 16, 1, a), 0, "an IV and nothing else")
	port.AssertEq(emonT, port.CryptoAesDecrypt(port.HexBlob("000102030405060708090a0b0c0d0e0f"), 0, 16, port.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489 ffff"), 0, 34, 1, b), 5, "a ragged tail is dropped")
	port.AssertEq(emonT, port.CryptoAesDecrypt(port.HexBlob("0001020304"), 0, 5, port.HexBlob("0f0e0d0c0b0a09080706050403020100 181547ce6a5438cb22241856b35cc489"), 0, 32, 1, c), -1, "a key of the wrong size")
	port.AssertEq(emonT, port.CellsLen(c), 0, "nothing appended")
}
